exempt = (input('exempt_assets') || {})['CKV_AWS_20'] || []

control 'CKV_AWS_20' do
  title 'S3 Bucket has an ACL defined which allows public READ access'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_s3_bucket resources that actually exist, read through the stock
    inspec-aws aws_s3_bucket resource.
  DESC

  desc 'rationale', <<~RATIONALE
    A bucket ACL granting public READ exposes every object to the internet,
    and the exposure is invisible from inside the account.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: S3 Bucket has an ACL defined which allows public READ
    access.
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_s3_bucket:

      resource "aws_s3_bucket_public_access_block" "example" {
        bucket                  = aws_s3_bucket.example.id
        block_public_acls       = true
        ignore_public_acls      = true
        block_public_policy     = true
        restrict_public_buckets = true
      }

    Out of band — aws_s3_bucket:

      aws s3api put-public-access-block --bucket <name> \
        --public-access-block-configuration \
        BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
  FIX

  tag checkov_id:            'CKV_AWS_20'
